def sort_dicts(items: list, key: str, reverse: bool = False) -> list:
    """Ordena lista de dicts pela chave informada."""
    return sorted(items, key=lambda x: x[key], reverse=reverse)

from functools import lru_cache

@lru_cache(maxsize=None)
def fibonacci(n: int) -> int:
    """Retorna o n-ésimo número de Fibonacci usando memoização."""
    if n <= 1:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

import asyncio
import aiohttp

async def fetch_json(url: str) -> dict:
    """Busca JSON de uma URL de forma assíncrona."""
    async with aiohttp.ClientSession() as session:
        async with session.get(url) as response:
            response.raise_for_status()
            return await response.json()

def get_json(url: str) -> dict:
    return asyncio.run(fetch_json(url))

import heapq
from dataclasses import dataclass, field
from typing import Any

@dataclass(order=True)
class PriorityItem:
    priority: int
    item: Any = field(compare=False)

class PriorityQueue:
    """Fila de prioridade min-heap."""
    def __init__(self):
        self._heap = []

    def push(self, item: Any, priority: int):
        heapq.heappush(self._heap, PriorityItem(priority, item))

    def pop(self) -> Any:
        return heapq.heappop(self._heap).item

    def __len__(self):
        return len(self._heap)
